import java.util.Scanner;

public class Main {
    static final int MAXN = 300005;
    static long[][] dpTable = new long[27][MAXN];
    static int[] factorial = new int[MAXN];
    static int[] invFactorial = new int[MAXN];

    static long fastPow(long base, int power, int mod) {
        long result = 1;
        while (power > 0) {
            if ((power & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            power >>= 1;
        }
        return result;
    }

    static int permute(int n, int m, int mod) {
        return (int)((long)factorial[n] * invFactorial[n - m] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int K = sc.nextInt();
        int MOD = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(fastPow(K, n, MOD));
            sc.close();
            return;
        }

        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (int)((long)factorial[i - 1] * i % MOD);
        }

        invFactorial[n] = (int)fastPow(factorial[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) {
            invFactorial[i] = (int)((long)invFactorial[i + 1] * (i + 1) % MOD);
        }

        dpTable[0][0] = 1L;
        for (int k = 0; k < K; k++) {
            for (int i = 1; i <= n; i++) {
                if ((i & n) != i) continue;
                int block_mask = 1 << (31 - Integer.numberOfLeadingZeros(i));
                long res = 0L;
                int cnt = 0;
                for (int j = i - block_mask; j >= 0; j = (j - 1) & i) {
                    int j_plus = j + block_mask;
                    res += dpTable[k][i ^ j_plus] * invFactorial[j_plus];
                    cnt++;
                    if (cnt == 17) {
                        res %= MOD;
                        cnt = 0;
                    }
                    if (j == 0) break;
                }
                res %= MOD;
                dpTable[k + 1][i] = res;
            }
        }

        int totalAns = 0;
        for (int i = 0; i <= K; i++) {
            totalAns = (int)((totalAns + (long)factorial[n] * dpTable[i][n] % MOD * permute(K, i, MOD)) % MOD);
        }

        System.out.println((int)((fastPow(K, n, MOD) + MOD - totalAns) % MOD));
        sc.close();
    }
}
